import DefaultBackend
import Foundation
import ImageFormats
import SwiftCrossUI

// P84: does Image draw SVG, the same on every backend?
//
// The number was checked: `ls testapp` gives P0..P83.
//
// Written 2026-10-09 with the pure-Swift SVG renderer (Sources/SwiftCrossUI/SVG).
// Five samples: the three KiCad board exports from SoftPCB (microstrip, spiral,
// meander), a feature sheet (path commands and arcs, nonzero/evenodd, caps and
// joins, transforms, opacity, mm units and viewBox, dashes, CSS), and a sheet
// of things the renderer does NOT draw. For each: SwiftCrossUI's rasterisation
// on the left, macOS CoreSVG's on the right (an embedded PNG, the same fixture
// the golden tests use, so every platform shows the same reference), the
// rasterisation size and time, the per-pixel difference from the reference,
// and the list of unsupported items ("none" when empty).
//
// Pass: left and right look alike on every sample but the last; the
// difference line reads max <= 96, mean <= 0.5, under 0.5% over 16 (the golden
// tests' bounds); buttons 1-5 pick the sample; "larger"/"smaller" change the raster size line and the left
// image stays sharp; the last sample lists six unsupported items and draws
// each place in magenta, with a magenta flag in the top-left corner.
// Fail: an empty or blank left image, a shape missing or moved, or an
// unsupported item that is neither listed nor outlined.
//
// The fixtures below the marker are generated from
// Tests/SwiftCrossUITests/SVGFixtures by test_support/make_P84_fixtures.zsh;
// do not edit them by hand.
//
// P84:Image 能否畫出 SVG,而且在每個 backend 上都一樣?編號查過:`ls testapp` 給出 P0..P83。
// 2026-10-09 撰寫，配合純 Swift SVG 算繪器。五個樣本：SoftPCB 的三份 KiCad 電路板匯出檔、一張功能表、
// 一張「算繪器不畫的東西」表。每一個樣本：左邊是 SwiftCrossUI 的點陣化，右邊是 macOS CoreSVG 的結果
// (內嵌 PNG,與黃金測試同一份 fixture,因此每個平台顯示同一張參考圖),以及點陣化尺寸與時間、
// 與參考圖的逐像素差異、不支援項目清單(空的時候顯示 none)。
// 通過：除了最後一個樣本，左右兩邊看起來一樣；差異列為 max <= 96、mean <= 0.5、超過 16 者不到 0.5%;
// 按鈕 1-5 選樣本；larger/smaller 會改變點陣尺寸列，左圖保持清晰；最後一個樣本列出六個不支援項目，每一處以洋紅色標出，
// 左上角有洋紅色旗標。失敗：左圖空白、形狀缺漏或位移、或某個不支援項目既未列出也未框出。
// 標記以下的 fixture 由 test_support/make_P84_fixtures.zsh 從 Tests/SwiftCrossUITests/SVGFixtures 產生，
// 請勿手改。

struct P84Sample {
    let name: String
    let document: SVGDocument
    let reference: ImageFormats.Image<RGBA>?
    /// Rasterised at the reference's size (640 x 400) once, at launch.
    let fixedRasterMillis: Double
    let difference: String

    static let referenceWidth = 640
    static let referenceHeight = 400

    static let all: [P84Sample] = P84Fixtures.samples.map { fixture in
        let svgBytes = Data(base64Encoded: fixture.svg, options: .ignoreUnknownCharacters) ?? Data()
        let document: SVGDocument
        do {
            document = try SVGDocument(data: Array(svgBytes))
        } catch {
            document = try! SVGDocument(string: "<svg xmlns='http://www.w3.org/2000/svg' width='10' height='10'/>")
        }
        var reference: ImageFormats.Image<RGBA>? = nil
        if let png = fixture.png,
            let data = Data(base64Encoded: png, options: .ignoreUnknownCharacters)
        {
            reference = try? ImageFormats.Image<RGBA>.load(from: Array(data), usingFileExtension: "png")
        }
        let start = Date()
        let raster = document.rasterize(width: referenceWidth, height: referenceHeight)
        let millis = Date().timeIntervalSince(start) * 1000
        let difference: String
        if let reference {
            difference = P84Sample.compare(raster, reference)
        } else {
            difference = "no reference (CoreSVG not used for this sample)"
        }
        return P84Sample(
            name: fixture.name, document: document, reference: reference,
            fixedRasterMillis: millis, difference: difference)
    }

    /// Premultiplied per-pixel difference, 0...255, as SVGTests measures it.
    static func compare(_ a: ImageFormats.Image<RGBA>, _ b: ImageFormats.Image<RGBA>) -> String {
        guard a.width == b.width, a.height == b.height else { return "sizes differ" }
        var maximum = 0.0
        var total = 0.0
        var over = 0
        for pixel in 0..<(a.width * a.height) {
            let index = pixel * 4
            let alphaA = Double(a.bytes[index + 3]) / 255
            let alphaB = Double(b.bytes[index + 3]) / 255
            var largest = 0.0
            for channel in 0..<4 {
                let va = channel == 3 ? alphaA * 255 : Double(a.bytes[index + channel]) * alphaA
                let vb = channel == 3 ? alphaB * 255 : Double(b.bytes[index + channel]) * alphaB
                largest = max(largest, abs(va - vb))
                total += abs(va - vb)
            }
            maximum = max(maximum, largest)
            if largest > 16 { over += 1 }
        }
        let pixels = Double(a.width * a.height)
        return String(
            format: "max %.0f, mean %.3f, %.3f%% of pixels over 16", maximum, total / (pixels * 4),
            Double(over) * 100 / pixels)
    }
}

@main
@HotReloadable
struct P84SVGApp: App {
    var body: some Scene {
        WindowGroup("P84 SVG") {
            #hotReloadable {
                P84View()
            }
        }
        .defaultSize(width: 560, height: 720)
    }
}

struct P84View: View {
    @State var index = 0
    @State var sizeIndex = 1
    @Environment(\.windowScaleFactor) var scale

    /// Widths in points for each image; the pair has to fit a 393 pt phone.
    /// 每張圖的寬度(點);兩張並排要放得進 393 點寬的手機。
    let widths = [96, 120, 168]

    var body: some View {
        let sample = P84Sample.all[index]
        let width = widths[sizeIndex]
        let height = Int((Double(width) * 0.625).rounded())
        let pixelWidth = Int((Double(width) * scale).rounded())
        let pixelHeight = Int((Double(height) * scale).rounded())
        // Timed here with the same call Image makes for this size.
        // 在此以 Image 對這個尺寸所做的同一個呼叫計時。
        let start = Date()
        _ = sample.document.rasterize(width: pixelWidth, height: pixelHeight)
        let displayMillis = Date().timeIntervalSince(start) * 1000

        return VStack(alignment: .leading, spacing: 8) {
            Text("P84: SVG").font(.system(size: 18))
            Text("backend -> \(String(describing: DefaultBackend.self))")
            // Fixed-width controls first and the changing text after them, so
            // every button stays where the action files click it.
            // 固定寬度的控制項在前、會變動的文字在後，讓每個按鈕都留在動作檔點擊的位置。
            HStack(spacing: 8) {
                Text("sample")
                ForEach(Array(P84Sample.all.indices), id: \.self) { number in
                    Button("\(number + 1)") { index = number }
                }
            }
            Text("\(index + 1)/\(P84Sample.all.count) \(sample.name)")
            HStack(spacing: 8) {
                Button("smaller") { sizeIndex = max(0, sizeIndex - 1) }
                Button("larger") { sizeIndex = min(widths.count - 1, sizeIndex + 1) }
                Text("\(width) x \(height) pt")
            }
            HStack(alignment: .top, spacing: 8) {
                VStack(alignment: .leading, spacing: 4) {
                    Text("SwiftCrossUI")
                    Image(sample.document)
                        .resizable()
                        .frame(width: Double(width), height: Double(height))
                        .border(Color.gray)
                }
                VStack(alignment: .leading, spacing: 4) {
                    Text("CoreSVG reference")
                    if let reference = sample.reference {
                        Image(reference)
                            .resizable()
                            .frame(width: Double(width), height: Double(height))
                            .border(Color.gray)
                    } else {
                        Text("none")
                    }
                }
            }
            Text(
                "raster \(pixelWidth) x \(pixelHeight) px (scale \(String(format: "%.3g", scale))) in \(String(format: "%.1f", displayMillis)) ms"
            )
            Text(
                "raster \(P84Sample.referenceWidth) x \(P84Sample.referenceHeight) px in \(String(format: "%.1f", sample.fixedRasterMillis)) ms"
            )
            Text("difference: \(sample.difference)")
            Text("unsupported: \(sample.document.diagnostics.isEmpty ? "none" : "\(sample.document.diagnostics.count)")")
            ForEach(Array(sample.document.diagnostics.enumerated()), id: \.offset) { item in
                Text("  \(item.element.description)")
            }
        }
        .padding(12)
    }
}

